int partition(vector& countries, int low, int high) {
 double pivot = countries[high].gdp;
 int i = low - 1;
 for (int j = low; j < high; j++) {
 if (countries[j].gdp < pivot) {
 i++;
 swap(countries[i], countries[j]);
 }
 }
 swap(countries[i + 1], countries[high]);
 return i + 1;
}
void quickSort(vector& countries, int low, int high) {
